def sign_jwt(sub: str) -> str:
    now = datetime.utcnow()
    payload = {"sub": sub, "iat": int(now.timestamp()), "exp": int((now + timedelta(minutes=JWT_EXPIRES_MIN)).timestamp())}
    return jwt.encode(payload, JWT_SECRET, algorithm="HS256")

def decode_jwt(token: str) -> Dict[str, Any]:
    return jwt.decode(token, JWT_SECRET, algorithms=["HS256"])

def extract_token_from_request(request: Request) -> Optional[str]:
    auth = request.headers.get("authorization") or request.headers.get("Authorization")
    if auth and auth.lower().startswith("bearer "):
        return auth.split(" ", 1)[1].strip()
    return None

async def resolve_user_from_request(request: Request, body_token: Optional[str] = None) -> Optional[str]:
    token = body_token or extract_token_from_request(request)
    if not token:
        return None
    try:
        payload = decode_jwt(token)
        sub = payload.get("sub")
        if isinstance(sub, str) and len(sub) > 0:
            return sub
        return None
    except Exception:
        return None

async def create_job(kind: str, created_by: Optional[str], payload: Dict[str, Any]) -> str:
    jid = uuid.uuid4().hex
    now = _now_iso()
    conn = await db()
    await conn.execute(
        "INSERT INTO jobs (id, type, status, created_at, updated_at, created_by, payload, result, error) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (jid, kind, "running", now, now, created_by, _json_dumps(payload), None, None),
    )
    await conn.commit()
    return jid

