async def robust_post_json(url: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    client = await http()
    last_exc: Optional[Exception] = None
    for attempt in range(HTTP_RETRIES + 1):
        try:
            r = await client.post(url, json=payload)
            r.raise_for_status()
            ct = r.headers.get("content-type", "")
            if "application/json" in ct or r.text.strip().startswith("{") or r.text.strip().startswith("["):
                return r.json()
            return {"raw": r.text}
        except Exception as e:
            last_exc = e
            if attempt < HTTP_RETRIES:
                await asyncio.sleep(min(0.25 * (2 ** attempt), 2.0))
            else:
                raise
    raise last_exc if last_exc else RuntimeError("Request failed")

async def proxy_worker(jid: str, url: str, payload: Dict[str, Any]) -> None:
    try:
        result = await robust_post_json(url, payload)
        await set_job_done(jid, result)
    except Exception as e:
        await set_job_failed(jid, str(e))

